package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.crypto.SecretDigester;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.RegistrationAccessTokenVO;

@RequiredArgsConstructor
public class RegistrationAccessTokenValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<RegistrationAccessTokenVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param service
   * @return
   */
  public Optional<String> getRegistrationAccessTokenStored(SecretDigester service) {
    return value.flatMap(val -> val.getRegistrationAccessTokenStored(service));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<RegistrationAccessTokenVO> getRegistrationAccessTokenValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public RegistrationAccessTokenVO readRegistrationAccessToken(final Optional<OauthClient> original,
      final ConstraintFailList fails) {
    return value.orElse(original.map(OauthClient::getRegistrationAccessTokenValue)
        .orElseGet(RegistrationAccessTokenVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param registrationAccessToken
   * @return
   */
  public T registrationAccessToken(RegistrationAccessTokenVO registrationAccessToken) {
    this.value = Optional.of(registrationAccessToken);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param registrationAccessToken
   * @return
   */
  public T registrationAccessToken(Optional<RegistrationAccessTokenVO> registrationAccessToken) {
    this.value = registrationAccessToken;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T registrationAccessTokenNull() {
    this.value = Optional.of(RegistrationAccessTokenVO.nullValue());
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param registrationAccessToken
   * @return
   */
  public T registrationAccessTokenPlain(String registrationAccessToken) {
    this.value = Optional.of(RegistrationAccessTokenVO.fromPlain(registrationAccessToken));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param registrationAccessToken
   * @return
   */
  public T registrationAccessTokenStored(String registrationAccessToken) {
    this.value = Optional.of(RegistrationAccessTokenVO.fromStored(registrationAccessToken));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetRegistrationAccessToken() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetRegistrationAccessTokenIfMatches(final String field) {
    if ("registrationAccessToken".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
